package com.group49.support.servlet;
import com.group49.support.dao.*;import com.group49.support.model.User;import com.group49.support.util.WebUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{private final TicketDao tickets=new TicketDao();private final NotificationDao notifications=new NotificationDao();@Override protected void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{User u=WebUtil.currentUser(req);try{long unread=notifications.unreadCount(u.id());req.setAttribute("stats",tickets.stats(u,unread));req.setAttribute("recentTickets",tickets.list(u,"","").stream().limit(6).toList());req.setAttribute("unreadCount",unread);req.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(req,res);}catch(Exception e){throw new ServletException("Unable to load dashboard",e);}}}
